    for i in range(41):
        mu = round(2.90 + 0.01 * i, 2)
        chi2 = sum(((y - gauss(x, A, mu, sigma)) / e) ** 2
                   for x, y, e in zip(xs, ys, errs))
        if best_chi2 is None or chi2 < best_chi2:
            best, best_chi2 = mu, chi2
