#include <iostream>
#include <vector>

class Buffer {
public:
    explicit Buffer(std::size_t n) : data_(n, 0.0) {}
    void set(std::size_t i, double x) { data_.at(i) = x; }
    double get(std::size_t i) const { return data_.at(i); }
private:
    std::vector<double> data_;
};

int main() {
    Buffer a(3);
    a.set(0, 1.5);
    Buffer b = a;
    b.set(0, 9.0);
    std::cout << a.get(0) << ' ' << b.get(0) << '\n';
}
```

