def bucket_quantile(q, edges, counts):
    rank = q * counts[-1]
    lower_edge = 0.0
    lower_count = 0.0
    for edge, count in zip(edges, counts):
        if count >= rank:
            inside = count - lower_count
            fraction = (rank - lower_count) / inside
            return lower_edge + fraction * (edge - lower_edge)
        lower_edge = edge
        lower_count = count
    return edges[-1]

