def auc(y_true, scores):
    sig = [s for y, s in zip(y_true, scores) if y == 1]
    bkg = [s for y, s in zip(y_true, scores) if y == 0]
    total = 0.0
    for s in sig:
        for b in bkg:
            if s > b:
                total += 1
            elif s == b:
                total += 0.5
    return total / (len(sig) * len(bkg))

